{"code": "async (page) => {
    // Wait for the iframe to load
    const frame = page.frame({ url: /pdf/ });
    if (!frame) {
        return 'No PDF frame found';
    }
    // Try to get text from the PDF viewer
    const text = await frame.evaluate(() => {
        const textLayer = document.querySelector('.textLayer');
        if (textLayer) {
            return textLayer.innerText;
        }
        // Fallback: get all text in body
        return document.body.innerText;
    });
    return text.slice(0, 5000) + (text.length > 5000 ? '...' : '');
}"}

