{"code": "async (page) => {
    const frame = page.frame({ url: /pdf/ });
    if (!frame) {
        return 'No PDF frame found';
    }
    const fullText = await frame.evaluate(() => {
        // Get all text layers
        const textLayers = document.querySelectorAll('.textLayer');
        let text = '';
        textLayers.forEach(layer => {
            text += layer.innerText + '\n';
        });
        // If no text layers, fallback to body text
        if (!text.trim()) {
            text = document.body.innerText;
        }
        return text;
    });
    return fullText;
}"}

