{"function": "async (page) => {
  const url = 'https://journals.le.ac.uk/index.php/jist/article/download/733/684/1496';
  const results = [];

  for (let i = 0; i < 10; i++) {
    try {
      const response = await page.goto(url, { waitUntil: 'load' });
      const buffer = await response.body();
      results.push({
        attempt: i + 1,
        status: response.status(),
        size: buffer.length,
        firstBytes: buffer.slice(0, 100).toString('hex')
      });
      // Navigate back or reload
      await page.waitForTimeout(100);
    } catch (error) {
      results.push({ attempt: i + 1, error: error.message });
    }
  }

  return results;
}"}

